package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="conventions")
public class Convention { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="partner_name") private String partnerName; @Column(name="partner_country") private String partnerCountry; @Column(name="start_date") private LocalDate startDate; @Column(name="end_date") private LocalDate endDate; @Column(length=5000) private String description; @Column(name="document_url") private String documentUrl; public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getPartnerName(){return partnerName;} public void setPartnerName(String partnerName){this.partnerName=partnerName;} public String getPartnerCountry(){return partnerCountry;} public void setPartnerCountry(String partnerCountry){this.partnerCountry=partnerCountry;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate startDate){this.startDate=startDate;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate endDate){this.endDate=endDate;} public String getDescription(){return description;} public void setDescription(String description){this.description=description;} public String getDocumentUrl(){return documentUrl;} public void setDocumentUrl(String documentUrl){this.documentUrl=documentUrl;} public boolean isActive(){return endDate==null || !endDate.isBefore(LocalDate.now());} }
